use std::{env, fmt::Write, fs, path::PathBuf};

use jayjay_core::diff_palettes;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let output = PathBuf::from(env::args().nth(1).ok_or("expected output directory")?);
    let mut css =
        String::from("/* Generated by export-web-themes; edit the Rust palette catalog. */\n");
    let mut catalog = String::from(
        "// Generated by export-web-themes; edit the Rust palette catalog.\nexport const diffThemes = [\n",
    );
    let mut bindings = String::from(
        "[data-jj-theme-light][data-jj-theme-dark] {\n  --jj-diff-gutter-opacity: 1;\n",
    );
    for (index, palette) in diff_palettes().into_iter().enumerate() {
        writeln!(
            catalog,
            "  {{ id: {:?}, name: {:?}, dark: {} }},",
            palette.id, palette.name, palette.is_dark
        )?;
        let side = if palette.is_dark { "dark" } else { "light" };
        writeln!(css, "[data-jj-theme-{side}={:?}] {{", palette.id)?;
        let c = palette.colors;
        for (name, value) in [
            ("context-bg", c.context_bg),
            ("text", c.text_context),
            ("added-bg", c.added_bg),
            ("removed-bg", c.removed_bg),
            ("added-text", c.text_added),
            ("removed-text", c.text_removed),
            ("word-added", c.added_word_bg),
            ("word-removed", c.removed_word_bg),
            ("gutter-bg", c.gutter_bg),
            ("gutter-fg", c.gutter_fg),
            ("gutter-added", c.gutter_added_fg),
            ("gutter-removed", c.gutter_removed_fg),
            ("separator-bg", c.separator_bg),
            ("dim", c.text_dim),
            ("keyword", c.tok_keyword),
            ("string", c.tok_string),
            ("comment", c.tok_comment),
            ("number", c.tok_number),
            ("type", c.tok_type),
        ] {
            writeln!(css, "  --jj-diff-{side}-{name}: #{value:06x};")?;
            if index == 0 {
                writeln!(
                    bindings,
                    "  --jj-diff-{name}: light-dark(var(--jj-diff-light-{name}), var(--jj-diff-dark-{name}));"
                )?;
            }
        }
        writeln!(
            css,
            "  --jj-diff-{side}-stripe: #{:06x}{:02x};",
            c.group_stripe,
            (c.group_stripe_alpha * 255.0).round() as u8
        )?;
        css.push_str("}\n");
    }
    bindings.push_str("  --jj-diff-stripe: light-dark(var(--jj-diff-light-stripe), var(--jj-diff-dark-stripe));\n}\n");
    css.push_str(&bindings);
    catalog.push_str("] as const;\n");
    fs::create_dir_all(&output)?;
    fs::write(output.join("diffThemes.css"), css)?;
    fs::write(output.join("diffThemes.ts"), catalog)?;
    Ok(())
}
